SYSTEM ← {
  STATE ← ∅
  QUEUE ← []
  ACTIVE ← false
}

INIT ⟶ {
  SYSTEM.STATE ← {
    time ← 0
    cycle ← 0
    memory ← ∅
  }
  SYSTEM.QUEUE ← []
  SYSTEM.ACTIVE ← true
  RETURN status: "initialized"
}

PROCESS(input) ⟶ {
  IF SYSTEM.ACTIVE {
    FOR item ∈ input {
      QUEUE.push({
        data ← item
        timestamp ← SYSTEM.STATE.time
        priority ← evaluate(item)
      })
    }
    WHILE QUEUE.length > 0 {
      current ← QUEUE.pop()
      SYSTEM.STATE.memory ← SYSTEM.STATE.memory ∪ {current}
      SYSTEM.STATE.cycle ← SYSTEM.STATE.cycle + 1
    }
    RETURN {
      processed ← SYSTEM.STATE.cycle
      timestamp ← SYSTEM.STATE.time
    }
  }
  ELSE {
    RETURN error: "system_inactive"
  }

